use std::io::{Read,Write};use spore_core::{cell_actor_geometry_projection_v1::Output,cell_actor_frame_update_v1::{evaluate,Input,Handoff}};
fn main()->Result<(),Box<dyn std::error::Error>>{let mut data=Vec::new();std::io::stdin().read_to_end(&mut data)?;if data.len()!=64{return Err("expected 4 cases".into())}let mut out=Vec::new();for row in data.chunks_exact(16){let w=|i:usize|u32::from_le_bytes(row[i*4..i*4+4].try_into().unwrap());let slot=w(0);let r=evaluate(Input{slot,manager_token:1,geometry:Some(Output{center:[w(1),w(2),0],scalar:w(3)}),stable_disjoint:true}).map_err(|e|format!("{e:?}"))?;let words=match r{Handoff::Skipped=>[0,0,0,0,0,0,0,0,slot],Handoff::PendingUpdate{manager_token,slot,min,max}=>[1,1,manager_token,slot,min[0],min[1],max[0],max[1],slot]};for x in words{out.extend(x.to_le_bytes())}}std::io::stdout().write_all(&out)?;Ok(())}
